<!doctype html><html lang="en" data-theme="<?=esc($_COOKIE['atlas_theme']??'light')?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#173b6c"><title>My Atlas</title><link rel="manifest" href="<?=esc(url_for('manifest.json'))?>"><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="mobile-work-body"><main class="mobile-work"><header><span class="brand-mark">A</span><div><small>MY ATLAS</small><h1>Hi, <?=esc(explode(' ',$user['name'])[0])?></h1></div><a href="<?=esc(url_for('notifications'))?>">Alerts <?=$dashboardUnread?'('.$dashboardUnread.')':''?></a></header><section class="mobile-hero"><small>NEXT SHIFT</small><?php if($nextShift):?><h2><?=esc(date('D, M j',strtotime($nextShift['shift_date'])))?></h2><strong><?=esc(date('g:i A',strtotime($nextShift['starts_at'])).'–'.date('g:i A',strtotime($nextShift['ends_at'])))?></strong><p><?=esc($nextShift['location_name'].' · '.$nextShift['department_name'])?></p><?php else:?><h2>No upcoming shift</h2><?php endif;?></section><section class="mobile-actions"><?php if($openEntry):?><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="clock_out"><button>Clock out</button></form><?php else:?><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="clock_in"><button>Clock in</button></form><?php endif;?><a href="<?=esc(url_for('requests'))?>">Request off</a><a href="<?=esc(url_for('trades'))?>">Trade shift</a><a href="<?=esc(url_for('callouts'))?>">Call out</a></section><section class="panel" style="padding:18px"><h2>Upcoming</h2><?php foreach(array_slice($myShifts,0,7) as $shift):?><div class="planning-row"><span><strong><?=esc(date('D, M j',strtotime($shift['shift_date'])))?></strong><small><?=esc(date('g:i A',strtotime($shift['starts_at'])).' · '.$shift['department_name'])?></small></span><?php if(isset($scheduleAcknowledgments[$shift['id']])):?><b class="state-pill covered">Acknowledged</b><?php endif;?></div><?php endforeach;?></section><nav class="mobile-tabbar"><a href="<?=esc(url_for('mobile'))?>">Today</a><a href="<?=esc(url_for('my-schedule'))?>">Schedule</a><a href="<?=esc(url_for('messages'))?>">Messages</a><a href="<?=esc(url_for('mobile-tools'))?>">Tools</a></nav></main><script src="<?=esc(url_for('assets/app.js'))?>"></script></body></html>
